std::vector<bool> is_interior(triangulation.number_of_faces(), false);
for (auto eit = triangulation.edges_begin(); eit != triangulation.edges_end(); ++eit) {
  if (triangulation.is_constrained(*eit)) {
    auto face_handle = triangulation.face(*eit, 0);
    if (face_handle != nullptr) {
      is_interior[face_handle->index()] = true;
    }
    face_handle = triangulation.face(*eit, 1);
    if (face_handle != nullptr) {
      is_interior[face_handle->index()] = true;
    }
  }
}
for (auto fit = triangulation.finite_faces_begin(); fit != triangulation.finite_faces_end(); ++fit) {
  if (!is_interior[fit->index()]) {
    int count = 0;
    for (auto vit = fit->vertices_begin(); vit != fit->vertices_end(); ++vit) {
      if (triangulation.is_vertex_on_constraint(*vit)) {
        count++;
      }
    }
    if (count % 2 == 1) {
      is_interior[fit->index()] = true;
    }
  }
}
for (auto fit = triangulation.finite_faces_begin(); fit != triangulation.finite_faces_end(); ++fit) {
  if (is_interior[fit->index()]) {
    fit->set_info(true); // label as interior
  } else {
    fit->set_info(false); // label as exterior
  }
}

